changeSet.sql:
ALTER TABLE IF EXISTS document.contracts             ADD COLUMN IF NOT EXISTS currency_id uuid;
ALTER TABLE IF EXISTS document.payments              ADD COLUMN IF NOT EXISTS currency_id uuid;
ALTER TABLE IF EXISTS document.payment_transactions  ADD COLUMN IF NOT EXISTS currency_id uuid;
ALTER TABLE IF EXISTS document.payment_requests      ADD COLUMN IF NOT EXISTS currency_id uuid;
ALTER TABLE IF EXISTS document.delay_requests        ADD COLUMN IF NOT EXISTS currency_id uuid;

UPDATE document.contracts t            SET currency_id = c.id FROM document.currencies c WHERE c.code = t.currency AND t.currency_id IS NULL;
UPDATE document.payments t             SET currency_id = c.id FROM document.currencies c WHERE c.code = t.currency AND t.currency_id IS NULL;
UPDATE document.payment_transactions t SET currency_id = c.id FROM document.currencies c WHERE c.code = t.currency AND t.currency_id IS NULL;
UPDATE document.payment_requests t     SET currency_id = c.id FROM document.currencies c WHERE c.code = t.currency AND t.currency_id IS NULL;
UPDATE document.delay_requests t       SET currency_id = c.id FROM document.currencies c WHERE c.code = t.currency AND t.currency_id IS NULL;

CREATE INDEX IF NOT EXISTS idx_contracts_currency_id ON document.contracts (currency_id);
